(\Pi y:A.B)[x:=s]=
\begin{cases}
\Pi y:A[x:=s].B,&y=x,\\
\Pi y:A[x:=s].B[x:=s],&y\ne x,\ y\notin\operatorname{FV}(s),\\
\Pi z:A[x:=s].(B[y:=z])[x:=s],&y\ne x,\ y\in\operatorname{FV}(s).
\end{cases}

(\lambda y:A.t)[x:=s]=
\begin{cases}
\lambda y:A[x:=s].t,&y=x,\\
\lambda y:A[x:=s].t[x:=s],&y\ne x,\ y\notin\operatorname{FV}(s),\\
\lambda z:A[x:=s].(t[y:=z])[x:=s],&y\ne x,\ y\in\operatorname{FV}(s).
\end{cases}

